SELECT jsonb_build_object('service_rows',(SELECT count(*) FROM platform_private.identity_service_authorization WHERE service_principal='worker-control-fixture.v1'),'generation',(SELECT security_generation FROM platform_private.identity_service_authorization WHERE service_principal='worker-control-fixture.v1'),'revoked',(SELECT revoked_at IS NOT NULL FROM platform_private.identity_service_authorization WHERE service_principal='worker-control-fixture.v1'),'exact_receipt_link',EXISTS(SELECT 1 FROM platform_private.identity_service_authorization a JOIN platform_private.identity_service_receipt r ON r.id=a.identity_receipt_id AND r.service_principal=a.service_principal AND r.security_generation=a.security_generation AND r.revoked_at IS NOT DISTINCT FROM a.revoked_at AND r.mutation_transaction_id=a.mutation_transaction_id WHERE a.service_principal='worker-control-fixture.v1'));
